def choose_move(observation):
    def _get_pos(v, default=(0, 0)):
        try:
            if isinstance(v, dict):
                return int(v.get("x", default[0])), int(v.get("y", default[1]))
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except:
            pass
        return default

    def _clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def _manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def _iter_points(obj):
        if not obj:
            return []
        pts = []
        try:
            for item in obj:
                if isinstance(item, dict):
                    if "position" in item:
                        pts.append(_get_pos(item.get("position")))
                    elif "x" in item and "y" in item:
                        pts.append(_get_pos(item))
                elif isinstance(item, (list, tuple)) and len(item) >= 2:
                    pts.append(_get_pos(item))
        except:
            return []
        return pts

    def _toward(src, dst):
        return [_clamp_step(src[0], dst[0]), _clamp_step(src[1], dst[1])]

    def _away(src, dst):
        return [_clamp_step(dst[0], src[0]), _clamp_step(dst[1], src[1])]

    env = observation.get("environment_name", "resource_collection")
    self_pos = _get_pos(observation.get("self_position", (0, 0)))
    opp_pos = _get_pos(observation.get("opponent_position", self_pos))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
