            return _toward(self_pos, best)
        return _toward(self_pos, opp_pos)

    resources = []
    for key in ("resources", "resource_positions", "resource_cells", "targets"):
        resources.extend(_iter_points(observation.get(key)))
    if resources:
        best = min(resources, key=lambda p: (_manhattan(self_pos, p), _manhattan(opp_pos, p)))
        return _toward(self_pos, best)

    center = (gw // 2, gh // 2) if gw and gh else opp_pos
    if gw and gh:
        return _toward(self_pos, center)
